  rp4_pre=()
  # --- monitor ---
  parity "monitor: nothing" monitor
  parity "monitor: an unknown subcommand, the nearest" monitor lst
  parity "monitor add: no SPEC" monitor add
  parity "monitor add: two" monitor add 800x600 640x480
