  # Interactive: its windows on the stand-in host, laid out as its layout.
  rp4_imain() { rp4_mons WAYLAND-1:1920x1080; echo fki > "$st/boxdir.name"; echo "$r/rt/omabox/fki" > "$st/boxdir"; : > "$st/interactive"; }
