      echo "    0   $lfk     G     5     1     -     -     -     -   sleep"; echo "    0   999999999     G    90     -     -     -     -     -   other"
      echo "    0   $lfk     G    20     2     3     -     -     -   sleep"; echo "    0   $lfk     G    40     2     -     1     -     -   sleep"; } > "$st/nv.out"; }
