  rp5c_unread() { rp5c_fix; mkdir -p "$ch/.config/omabox"; echo protect-ports=8080 > "$ch/.config/omabox/config"; chmod 000 "$ch/.config/omabox/config"; }
  if [ "$(id -u)" != 0 ]; then
